import{_ as i,c as e,o as l,ag as t}from"./chunks/framework.ymCRTBvy.js";const m=JSON.parse('{"title":"2.4_理解视图生命周期（ViewLifeCycle）","description":"","frontmatter":{},"headers":[],"relativePath":"swift/uikit/animation/2.4_理解视图生命周期（ViewLifeCycle）.md","filePath":"swift/uikit/animation/2.4_理解视图生命周期（ViewLifeCycle）.md"}'),d={name:"swift/uikit/animation/2.4_理解视图生命周期（ViewLifeCycle）.md"};function r(o,a,p,n,_,c){return l(),e("div",null,a[0]||(a[0]=[t('<h1 id="_2-4-理解视图生命周期-viewlifecycle" tabindex="-1">2.4_理解视图生命周期（ViewLifeCycle） <a class="header-anchor" href="#_2-4-理解视图生命周期-viewlifecycle" aria-label="Permalink to &quot;2.4_理解视图生命周期（ViewLifeCycle）&quot;">​</a></h1><h2 id="视图生命周期详解-📱" tabindex="-1">视图生命周期详解 📱 <a class="header-anchor" href="#视图生命周期详解-📱" aria-label="Permalink to &quot;视图生命周期详解 📱&quot;">​</a></h2><p>视图生命周期是iOS开发中一个至关重要的概念，它描述了视图从创建到销毁的整个过程。理解这个过程能帮助你更好地管理视图，优化性能，并避免潜在的bug。你可以把它想象成一个舞台剧，每个视图都是一个演员，在不同的时间点执行不同的任务。</p><h2 id="视图加载与初始化-🎬" tabindex="-1">视图加载与初始化 🎬 <a class="header-anchor" href="#视图加载与初始化-🎬" aria-label="Permalink to &quot;视图加载与初始化 🎬&quot;">​</a></h2><p>视图的生命周期始于它的加载和初始化。通常，这发生在以下两种情况：</p><ol><li><strong>从Storyboard或XIB加载：</strong> 当你使用Storyboard或XIB文件创建视图时，系统会自动加载并初始化视图。</li><li><strong>以编程方式创建：</strong> 你也可以使用代码手动创建视图，例如 <code>UIView()</code>。</li></ol><p>无论哪种方式，视图都会经历一系列的初始化过程。例如，<code>init(frame:)</code> 方法会被调用，你可以在这里设置视图的初始属性。</p><h2 id="视图即将显示-viewwillappear-animated-🌟" tabindex="-1">视图即将显示：viewWillAppear(_ animated:) 🌟 <a class="header-anchor" href="#视图即将显示-viewwillappear-animated-🌟" aria-label="Permalink to &quot;视图即将显示：viewWillAppear(_ animated:) 🌟&quot;">​</a></h2><p><code>viewWillAppear(_ animated:)</code> 方法在视图即将显示在屏幕上时被调用。这是一个绝佳的机会来执行一些准备工作，例如：</p><ul><li>更新视图的数据。</li><li>启动动画。</li><li>调整视图的布局。</li></ul><p>请记住，这个方法可能会被多次调用，例如当视图从后台返回时。</p><h2 id="视图已经显示-viewdidappear-animated-🎉" tabindex="-1">视图已经显示：viewDidAppear(_ animated:) 🎉 <a class="header-anchor" href="#视图已经显示-viewdidappear-animated-🎉" aria-label="Permalink to &quot;视图已经显示：viewDidAppear(_ animated:) 🎉&quot;">​</a></h2><p><code>viewDidAppear(_ animated:)</code> 方法在视图已经完全显示在屏幕上时被调用。你可以在这里执行一些需要视图完全可见才能完成的任务，例如：</p><ul><li>开始网络请求。</li><li>显示用户教程。</li><li>记录用户行为。</li></ul><p>这个方法也可能会被多次调用，所以请确保你的代码是幂等的。</p><h2 id="视图即将消失-viewwilldisappear-animated-👋" tabindex="-1">视图即将消失：viewWillDisappear(_ animated:) 👋 <a class="header-anchor" href="#视图即将消失-viewwilldisappear-animated-👋" aria-label="Permalink to &quot;视图即将消失：viewWillDisappear(_ animated:) 👋&quot;">​</a></h2><p><code>viewWillDisappear(_ animated:)</code> 方法在视图即将从屏幕上消失时被调用。这是一个很好的机会来执行一些清理工作，例如：</p><ul><li>停止动画。</li><li>保存数据。</li><li>取消网络请求。</li></ul><h2 id="视图已经消失-viewdiddisappear-animated-😥" tabindex="-1">视图已经消失：viewDidDisappear(_ animated:) 😥 <a class="header-anchor" href="#视图已经消失-viewdiddisappear-animated-😥" aria-label="Permalink to &quot;视图已经消失：viewDidDisappear(_ animated:) 😥&quot;">​</a></h2><p><code>viewDidDisappear(_ animated:)</code> 方法在视图已经完全从屏幕上消失时被调用。你可以在这里执行一些最终的清理工作，例如：</p><ul><li>释放资源。</li><li>取消订阅通知。</li></ul><p>理解这些方法及其调用时机，能让你更好地控制视图的行为，并创建更流畅、更高效的iOS应用。记住，视图生命周期是iOS开发的基础，掌握它将为你打开更广阔的编程世界！🚀</p>',22)]))}const h=i(d,[["render",r]]);export{m as __pageData,h as default};
